type taskResponseWhere[Q sqlite.Filterable] struct {
	cols      taskResponseColumns
	ID        sqlite.WhereMod[Q, string]
	CreatedAt sqlite.WhereMod[Q, time.Time]
	TaskID    sqlite.WhereMod[Q, string]
	Subject   sqlite.WhereMod[Q, string]
	Assignee  sqlite.WhereMod[Q, string]
	Outcome   sqlite.WhereMod[Q, string]
	Comment   sqlite.WhereMod[Q, string]
	Input     sqlite.WhereNullMod[Q, types.JSON[json.RawMessage]]
	R         taskResponseWhereR[Q]
}

func (taskResponseWhere[Q]) AliasedAs(alias string) taskResponseWhere[Q] {
	return buildTaskResponseWhere[Q](buildTaskResponseColumns(alias))
}

func buildTaskResponseWhere[Q sqlite.Filterable](cols taskResponseColumns) taskResponseWhere[Q] {
	return taskResponseWhere[Q]{
		cols:      cols,
		ID:        sqlite.Where[Q, string](cols.ID.Expression),
		CreatedAt: sqlite.Where[Q, time.Time](cols.CreatedAt.Expression),
		TaskID:    sqlite.Where[Q, string](cols.TaskID.Expression),
		Subject:   sqlite.Where[Q, string](cols.Subject.Expression),
		Assignee:  sqlite.Where[Q, string](cols.Assignee.Expression),
		Outcome:   sqlite.Where[Q, string](cols.Outcome.Expression),
		Comment:   sqlite.Where[Q, string](cols.Comment.Expression),
		Input:     sqlite.WhereNull[Q, types.JSON[json.RawMessage]](cols.Input.Expression),
		R:         taskResponseWhereR[Q]{cols: cols},
	}
}

// taskResponseWhereR holds the relationship-based filters of
// taskResponseWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type taskResponseWhereR[Q sqlite.Filterable] struct {
	cols taskResponseColumns
}

// HasTask filters parents that have a matching Task using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Tasks).
func (w taskResponseWhereR[Q]) HasTask(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := sqlite.Select(
		sm.Columns(sqlite.Raw("1")),
		sm.From(Tasks.NameExpr()),
		sm.Where(Tasks.Columns.ID.EQ(w.cols.TaskID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: sqlite.Exists(q)}
}
